57	/** Clamp a raw "extra GB to add" input to a valid, on-step, in-range amount (0 allowed). */
58	function normalizeExtraDiskAddGB(raw: unknown): number {
59	  const n = Math.round((Number(raw) || 0) / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
60	  return Math.max(0, Math.min(EXTRA_DISK_MAX_ADD_GB, n));
61	}
62	import { hostingAppCatalog } from "../worker/hosting";
63	import { fsList, fsMkdir, fsDelete, fsTargetFor, type HostingFsTarget } from "./hosting-fs";
64	import { hasChargeableCard, createCardSetupSession, CARD_SETUP_STARTED } from "./stripe-cards";
65	import { stripeConfigured } from "./stripe";
