67	export type HostingResult = { ok?: boolean; error?: string; accountId?: string };
68	
69	// The active-ish states that reserve a domain / occupy a node slot.
70	const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
71	
72	/** Least-loaded enabled+online node with account headroom. */
73	async function scheduleHostingNode(): Promise<{ id: string } | null> {
74	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
75	  if (!nodes.length) return null;
76	  const loads = await Promise.all(
77	    nodes.map(async (n) => ({
78	      node: n,
79	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
80	    })),
81	  );
82	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
83	  return withRoom.length ? { id: withRoom[0].node.id } : null;
84	}
85	
86	/** A free jailed username on the node, derived from the email + random salt. */
87	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
88	  for (let i = 0; i < 8; i++) {
89	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
90	    if (!isValidUnixUsername(name)) continue;
91	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
92	    if (!taken) return name;
93	  }
94	  throw new Error("Could not allocate a username — try again.");
95	}
