97	/**
98	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
99	 * as every other paid path: no spending while impersonating, verified email,
100	 * wallet charge in the same tx that creates the record. The account starts
101	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
102	 * enabled — see worker/hosting.ts).
103	 */
104	export async function orderHostingAccount(
105	  planId: string,
106	  domain: string,
107	  termMonthsRaw?: number,
108	  subdomainLabelRaw?: string,
109	  extraDiskGBRaw?: number,
110	): Promise<HostingResult> {
111	  const user = await requireUser();
112	  await assertNotImpersonating();
113	  const unverified = await emailVerificationError(user);
114	  if (unverified) return { error: unverified };
115	
116	  // OPTIONAL domain. An empty domain means "start me on a free temporary
117	  // `<username>.nxeon.cloud` subdomain, I'll connect a real domain later" — the
118	  // customer is never forced to own a domain to sign up. A REAL domain keeps every
119	  // cross-tenant guard it always had; the temp subdomain is derived from the
120	  // account's own per-node-unique username (below) so it can't collide with
121	  // anything a customer typed, and its uniqueness is still enforced by the SAME
122	  // atomic UNIQUE(hostname) claim inside the charge tx.
123	  const wantTemp = !String(domain ?? "").trim();
124	  let name = "";
125	  if (!wantTemp) {
126	    name = normalizeHostingDomain(domain);
127	    if (!name) return { error: "Enter a domain." };
128	    if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
129	  }
130	
131	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
132	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
133	
134	  if (!wantTemp) {
135	    // One account per domain across ALL customers — same cross-tenant guard as
136	    // email subscriptions (a shared vhost keys on server_name).
137	    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
138	    if (dupe) {
139	      return {
140	        error:
141	          dupe.userId === user.id
142	            ? "You already have a hosting account for this domain."
143	            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
144	      };
145	    }
146	    // Also reject if this hostname is already someone's subdomain or addon domain
147	    // (audit HIGH-2: the primary-order guard used to ignore those two tables).
148	    if (await isHostnameClaimed(name)) {
149	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
150	    }
151	  }
152	
153	  const node = await scheduleHostingNode();
154	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
155	
156	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
157	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
158	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
159	  // account/IP, or the promo is off) the account is created at FULL price. We
160	  // pre-check eligibility only to pick the balance gate: a first-time customer with
161	  // a $0 balance can still sign up free, a repeat one is gated against full price.
162	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
163	  // product the promo applies to. See firstMonthFreeAppliesTo.
164	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
165	  const campaign = promoCampaignFromCookie(await cookies());
166	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
167	  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
168	  // ONCE here, frozen onto the account, charged up front and read back at renewal —
169	  // so displayed === charged === renewed. A malformed term falls back to monthly.
170	  const term = normalizeProductTerm(termMonthsRaw);
171	  const annualPct = await annualDiscountPct();
172	  const limits = planLimits(plan);
173	  // Optional extra storage bought at deploy (on-step, in-range). Priced per-GB/month
174	  // at the SAME rate VPS extra disk uses and multiplied over the whole term. It is an
175	  // ADD-ON: never discounted by the term promo (the free month applies to the plan
176	  // only), so `extraTermCents` is added AFTER the credit — displayed === charged.
177	  const extraGB = normalizeExtraDiskAddGB(extraDiskGBRaw);
178	  if (effectiveDiskGB(limits.diskGB, extraGB) > EXTRA_DISK_MAX_TOTAL_GB) {
179	    return { error: `Storage tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — choose a smaller add-on.` };
180	  }
181	  const perGbCents = await extraDiskPerGbCents();
182	  const extraTermCents = extraDiskCentsAt(extraGB, perGbCents) * term;
183	  // PLAN term price (the promo-creditable part) vs the true TOTAL the customer pays.
184	  const planTermCents = termPriceCents(plan.priceCents, term, annualPct);
185	  const fullCharge = planTermCents + extraTermCents;
186	  // First-month-free must credit EXACTLY ONE MONTH of the PLAN — never zero a whole
187	  // annual term, and never touch the storage add-on. `firstMonthCreditCents(planTermCents,
188	  // term)` returns the full plan charge for a 1-month term (genuinely free first month)
189	  // and one month's share for the annual term; the storage add-on is always charged.
190	  const promoCharge = Math.max(0, planTermCents - firstMonthCreditCents(planTermCents, term)) + extraTermCents;
191	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
192	  const anticipated = eligible ? promoCharge : fullCharge;
193	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
194	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
195	  // Free temporary subdomain: derived from the just-allocated (per-node-unique)
196	  // username, validated the same way a real domain is and de-duplicated by the same
197	  // atomic hostname claim inside the tx. The advisory pre-check here is friendly UX
198	  // only — a collision across nodes is caught authoritatively by UNIQUE(hostname).
199	  if (wantTemp) {
200	    // A customer-CHOSEN free subdomain (`<label>.<base>`) if they picked one in the
201	    // wizard, else the auto-derived `<username>.<base>`. Either way it lives under our
202	    // `*.<HOSTING_SUBDOMAIN_BASE>` wildcard, so it resolves + gets HTTPS automatically
203	    // (no A record for the customer to set). The chosen label is validated here and
204	    // de-duplicated by the SAME atomic UNIQUE(hostname) claim inside the charge tx —
205	    // the wizard's live availability check (checkHostingSubdomain) is advisory UX only.
206	    const label = String(subdomainLabelRaw ?? "").trim().toLowerCase();
207	    if (label) {
208	      if (!isValidSubdomainLabel(label)) {
209	        return { error: "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
210	      }
211	      name = freeSubdomainFor(label);
212	      if (!isValidHostingDomain(name)) return { error: "That subdomain isn’t a valid hostname — try a different one." };
213	      if (await isHostnameClaimed(name)) {
214	        return { error: `${name} is already taken — please choose another subdomain.` };
215	      }
216	    } else {
217	      name = tempSubdomainFor(username);
218	      if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
219	      if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
220	    }
221	  }
222	
223	  let accountId = "";
224	  try {
225	    await db.$transaction(async (tx) => {
226	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
227	      let debitCents = fullCharge;
228	      let promoClaimId: string | null = null;
229	      // MONEY BUG FIX (2026-08-12): gate the claim on `eligible`, NOT `promoEnabled`.
230	      // claimFirstMonthFree INSERTs a redemption row and catches the P2002 unique
231	      // violation ("already redeemed") to return {claimed:false}. But Postgres POISONS
232	      // the whole transaction the instant any statement fails — a caught error does
233	      // NOT un-abort it — so the very next statement (debitWallet's updateMany) then
234	      // dies with 25P02 ("current transaction is aborted"). Result: EVERY repeat
235	      // customer who already used the free month could no longer place a hosting order
236	      // (the order failed, wallet never charged). `eligible` is the same authoritative
237	      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
238	      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
239	      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
240	      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
241	      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
242	      // full. So exactly one free month is ever granted.
243	      if (eligible) {
244	        const claim = await claimFirstMonthFree(tx, {
245	          userId: user.id,
246	          ipHash,
247	          serviceType: "HOSTING",
248	          campaign,
249	          chargedCents: promoCharge,
250	        });
251	        if (claim.claimed) {
252	          debitCents = promoCharge;
253	          promoClaimId = claim.id;
254	        }
255	      }
256	      const note = (debitCents < fullCharge ? " — First month free" : "") + (extraGB > 0 ? ` + ${extraGB} GB storage` : "");
257	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
258	      // so the customer sees the yearly commitment AND its real per-month rate. Uses the
259	      // PLAN per-month rate (the add-on has its own $/GB/mo shown in the storage note).
260	      const effMonthly = term > 1 ? Math.round(planTermCents / term) : 0;
261	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
262	      await debitWallet(tx, user.id, debitCents);
263	      await tx.walletTransaction.create({
264	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
265	      });
266	      const acct = await tx.hostingAccount.create({
267	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
268	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
269	        // (identical at runtime then — see lib/order.ts's Server create).
270	        data: {
271	          userId: user.id,
272	          hostingNodeId: node.id,
273	          planId: plan.id,
274	          username,
275	          primaryDomain: name,
276	          status: "PENDING",
277	          // Quota already folds in the purchased extra disk, so the node's setquota
278	          // (applyIsolation → taskApplyPlanLimits) provisions the right size with no
279	          // add-on awareness of its own.
280	          diskQuotaMB: effectiveDiskGB(limits.diskGB, extraGB) * 1024,
281	          extraDiskGB: extraGB,
282	          maxSites: limits.maxSites,
283	          maxDatabases: limits.maxDatabases,
284	          // The term this account was SOLD on, and the annual rate frozen at sale, so
285	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
286	          termMonths: term,
287	          annualDiscountPct: annualPct,
288	          expiresAt: addMonths(new Date(), term),
289	        } as Prisma.HostingAccountUncheckedCreateInput,
290	      });
291	      accountId = acct.id;
292	      // Atomic hostname claim in the SAME tx as the account row. A colliding
293	      // primaryDomain (another order, or someone's subdomain/addon of the same
294	      // name racing us past the advisory isHostnameClaimed check) fails here on
295	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
296	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
297	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
298	    });
299	  } catch (e) {
300	    if (isUniqueViolation(e)) {
301	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
302	    }
303	    // The generic message below is intentionally opaque to the customer, but the
304	    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
305	    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
306	    // table missing because a `prisma db push` didn't apply → the INSERT throws
307	    // here). Log it before swallowing. No money-logic change — the tx already rolled
308	    // back, so the wallet was NOT charged.
309	    console.error("[hosting.order] failed", {
310	      userId: user.id,
311	      planId,
312	      domain: name,
313	      code: (e as { code?: string })?.code,
314	      err: e instanceof Error ? e.message : e,
315	    });
316	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
317	  }
318	
319	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
320	  revalidatePath("/dashboard/hosting");
321	  return { ok: true, accountId };
322	}
323	
324	// ---------- Checkout wizard (payment-method-captured order) ------------------
325	//
326	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
327	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
328	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
329	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
330	// REFUSES to provision unless the account has a way to bill the renewal (a saved
331	// card OR a wallet balance that already covers one renewal), it is idempotent
332	// against double-submit, and it then delegates the ACTUAL charge to the audited
333	// `orderHostingAccount` above — one debit path, never a second one.
334	//
335	// displayed === charged === renewed: this action computes NO price of its own for
336	// the debit. The wallet debit + the first-month-free reserve→confirm→release
337	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
338	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
339	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
340	
341	export type HostingOrderInput = {
342	  planId: string;
343	  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
344	  domain?: string;
345	  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
346	  subdomainLabel?: string;
347	  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
348	  extraDiskGB?: number;
349	  termMonths?: number;
350	  /** Optional catalog app to auto-install after the account provisions. */
351	  appSlug?: string;
352	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
353	  idempotencyKey: string;
354	};
355	
356	export type HostingOrderResult =
357	  | { ok: true; accountId: string }
358	  | { error: string }
359	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
360	  | { needCard: true; renewalCents: number };
361	
362	/**
363	 * The full-price single renewal of a plan/term — the gate threshold, identical to
364	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
365	 */
366	async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
367	  const annualPct = await annualDiscountPct();
368	  const perGbCents = await extraDiskPerGbCents();
369	  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
370	}
371	
372	/** Place a hosting order from the checkout wizard. See the block comment above. */
373	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
374	  const user = await requireUser();
375	  await assertNotImpersonating();
376	  const unverified = await emailVerificationError(user);
377	  if (unverified) return { error: unverified };
378	
379	  const key = String(input.idempotencyKey ?? "").trim();
380	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
381	
382	  const term = normalizeProductTerm(input.termMonths);
383	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
384	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
385	
386	  // RENEWAL-METHOD GATE — the core fix. Never provision a paid product with no way
387	  // to bill the renewal. A saved card (charged off-session by the renewal sweep) OR
388	  // a wallet already holding one renewal's worth qualifies; otherwise the wizard
389	  // sends the customer to Stripe to capture a card (which also handles the $0-today
390	  // case, where no card would otherwise be collected).
391	  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
392	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
393	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
394	    return { needCard: true, renewalCents };
395	  }
396	
397	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
398	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
399	  // token table. A rapid resubmit or a network retry with the same key can't create
400	  // a second account or take a second debit.
401	  const sessionKey = `hostorder:${key}`;
402	  try {
403	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
404	  } catch (e) {
405	    if (isUniqueViolation(e)) {
406	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
407	      // A completed prior attempt: replay its result (no second charge).
408	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
409	      // A failed prior attempt: clear it so an explicit retry can proceed.
410	      if (prior?.status === "FAILED") {
411	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
412	      } else {
413	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
414	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
415	      }
416	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
417	      try {
418	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
419	      } catch {
420	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
421	      }
422	    } else {
423	      throw e;
424	    }
425	  }
426	
427	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
428	  // the free temporary subdomain. All money movement, the first-month-free atomic
429	  // claim and the hostname claim happen inside orderHostingAccount's transaction.
430	  const res = await orderHostingAccount(input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB);
431	  if (res.error || !res.accountId) {
432	    await db.fulfilledSession
433	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
434	      .catch(() => {});
435	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
436	  }
437	  await db.fulfilledSession
438	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
439	    .catch(() => {});
440	
441	  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
442	  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
443	  // side), so an ad blocker / privacy browser silently drops it and the campaign
444	  // never learns the signup happened. Firing it here too — with the SAME event_id
445	  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
446	  // conversion when the pixel DOES load, and still counts it when the pixel is
447	  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
448	  // Best-effort: sendMetaConversion never throws, and this runs after the order is
449	  // already committed, so tracking can never affect the charge.
450	  try {
451	    const [h, ck] = await Promise.all([headers(), cookies()]);
452	    await sendMetaConversion({
453	      eventName: "Subscribe",
454	      eventId: key,
455	      email: user.email,
456	      externalId: user.id,
457	      value: renewalCents / 100,
458	      currency: "USD",
459	      clientIp: clientIp(h),
460	      userAgent: h.get("user-agent") ?? undefined,
461	      // The Meta click/browser cookies are the strongest match signals for an
462	      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
463	      // Quality well above the email/IP-only baseline. Absent for organic visits.
464	      fbc: ck.get("_fbc")?.value || undefined,
465	      fbp: ck.get("_fbp")?.value || undefined,
466	      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
467	    });
468	  } catch {
469	    /* tracking is best-effort — the order is already placed and charged */
470	  }
471	
472	  // Optional one-click app install: queue it now so the worker installs it the
473	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
474	  // the (already-charged) order; the customer can install from the panel later.
475	  const slug = String(input.appSlug ?? "").trim();
476	  if (slug) {
477	    try {
478	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
479	    } catch {
480	      /* non-fatal: the account is created and charged; the app can be installed later */
481	    }
482	  }
483	
484	  revalidatePath("/dashboard/hosting");
485	  return { ok: true, accountId: res.accountId };
486	}
