490	 * Advisory UX for the deploy wizard — the authoritative de-dup is the atomic
491	 * UNIQUE(hostname) claim inside orderHostingAccount's charge tx, so a check that
492	 * says "available" can still lose a race and fail the order cleanly (no charge).
493	 */
494	export async function checkHostingSubdomain(
495	  labelRaw: string,
496	): Promise<{ available: boolean; fqdn: string; reason?: string }> {
497	  await requireUser();
498	  const label = String(labelRaw ?? "").trim().toLowerCase();
499	  const fqdn = freeSubdomainFor(label);
500	  if (!label) return { available: false, fqdn, reason: "Enter a subdomain." };
501	  if (!isValidSubdomainLabel(label)) {
502	    return { available: false, fqdn, reason: "Use 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
503	  }
504	  if (!isValidHostingDomain(fqdn)) {
505	    return { available: false, fqdn, reason: "That subdomain isn’t a valid hostname." };
506	  }
507	  if (await isHostnameClaimed(fqdn)) {
508	    return { available: false, fqdn, reason: "Already taken — try another." };
