513	/**
514	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
515	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
516	 * after provisioning. Generates DB credentials up front for apps that need one.
517	 */
518	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
519	  // WordPress is NOT an APP_RECIPES download — it installs via its own fully-
520	  // automated WORDPRESS_INSTALL task (WP-CLI). Route the wizard's one-click
521	  // WordPress here so it queues the right task with the same credential payload
522	  // installWordPress builds (mirrors that path). Any other slug must be a known
523	  // recipe app; an unknown slug is dropped (best-effort — never voids the order).
524	  if (slug === "wordpress") {
525	    if (maxDatabases < 1) return; // WordPress needs a database — no budget, skip rather than fail
526	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
527	    if (!acct) return;
528	    const dbName = `${acct.username}_wp`.slice(0, 64);
529	    const dbUser = dbName.slice(0, 32);
530	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
531	    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
532	    await db.hostingTask.create({
533	      data: {
534	        accountId,
535	        kind: "WORDPRESS_INSTALL",
536	        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
537	      },
538	    });
539	    return;
540	  }
541	  const app = hostingAppCatalog().find((x) => x.slug === slug);
542	  if (!app) return;
543	  let payload: Record<string, unknown> = { slug };
544	  if (app.needsDb) {
545	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
546	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
547	    if (!acct) return;
548	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
549	    const dbUser = dbName.slice(0, 32);
550	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
551	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
552	  }
553	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
554	}
