711	/** Create a scoped database for an account (within the plan's maxDatabases). */
712	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
713	  const user = await requireUser();
714	  await assertNotImpersonating();
715	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
716	  if (!a) return { error: "Account not found." };
717	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
718	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
719	  // A short, safe suffix keyed off the account username: <user>_<slug>.
720	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
721	  const name = `${a.username}_${slug}`.slice(0, 64);
722	  const dbUser = name.slice(0, 32);
723	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
724	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
725	  // Count + create in ONE serializable transaction, so concurrent creates can't
726	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
727	  try {
728	    await db.$transaction(async (tx) => {
729	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
730	      if (n >= a.maxDatabases) throw new Error("CAP");
731	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
732	    }, { isolationLevel: "Serializable" });
733	  } catch (e) {
734	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
735	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
736	    return { error: "A database with that name already exists, or the request raced — try again." };
737	  }
738	  revalidatePath("/dashboard/hosting");
739	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
740	  return { ok: true, password };
741	}
