759	export async function revealHostingDbPassword(dbId: string): Promise<{ password?: string; error?: string }> {
760	  const user = await requireUser();
761	  await assertNotImpersonating();
762	  const d = await db.hostingDatabase.findUnique({
763	    where: { id: dbId },
764	    select: { passwordEnc: true, account: { select: { userId: true } } },
765	  });
766	  if (!d) return { error: "Not found." };
767	  if (d.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
768	  if (!d.passwordEnc) return { error: "No stored password — reset it to set a new one." };
769	  const pw = decryptSecret(d.passwordEnc);
