774	/**
775	 * Reset a hosting database's password (owner or admin, never while impersonating).
776	 * Generates a new alphanumeric password, queues a RESET_DB_PASSWORD task that runs
777	 * `ALTER USER … IDENTIFIED BY …` on the node, and stores the new (encrypted) value
778	 * so it can be viewed later. Returned ONCE to the caller for display. No money logic.
779	 */
780	export async function resetHostingDbPassword(dbId: string): Promise<{ password?: string; error?: string }> {
781	  const user = await requireUser();
782	  await assertNotImpersonating();
783	  const d = await db.hostingDatabase.findUnique({
784	    where: { id: dbId },
785	    select: { id: true, dbUser: true, accountId: true, account: { select: { userId: true } } },
786	  });
787	  if (!d) return { error: "Not found." };
788	  if (d.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
789	  const newPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
790	  await db.hostingTask.create({
791	    data: {
792	      accountId: d.accountId,
793	      // New enum value applied by `prisma db push` at promote (additive/safe; the
794	      // symlinked prod Prisma client's types predate it until regenerated — cast,
795	      // identical at runtime, same pattern as HostingAccount.termMonths above).
796	      kind: "RESET_DB_PASSWORD" as Prisma.HostingTaskUncheckedCreateInput["kind"],
797	      payload: JSON.stringify({ dbUser: d.dbUser, passEnc: encryptSecret(newPass) }),
798	    },
799	  });
800	  await db.hostingDatabase.update({ where: { id: d.id }, data: { passwordEnc: encryptSecret(newPass) } });
801	  revalidatePath("/dashboard/hosting");
802	  return { password: newPass };
803	}
