805	/**
806	 * Install the per-account Adminer database manager (or return the existing one).
807	 * Owner-or-admin + not-impersonating (same discipline as every resource-creating
808	 * action). Queues an INSTALL_DBTOOL task that drops Adminer into THIS account's
809	 * webroot at a randomized path served by the account's own FPM socket. The
810	 * customer logs in with their own SCOPED DB user, so a leaked path grants no
811	 * cross-tenant access (see the worker handler's SECURITY note). Idempotent: if the
812	 * tool is already installed, returns its path without re-queuing.
813	 */
814	export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
815	  const user = await requireUser();
816	  await assertNotImpersonating();
817	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, dbToolPath: true } });
818	  if (!a) return { error: "Account not found." };
819	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
820	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
821	  if (a.dbToolPath) return { ok: true, url: a.dbToolPath };
822	  // Don't queue a second install while one is already in flight.
823	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "INSTALL_DBTOOL", status: { in: ["PENDING", "RUNNING"] } } });
824	  if (inFlight) return { ok: true };
825	  const token = randomBytes(16).toString("hex").slice(0, 32); // 32 lowercase hex chars
826	  if (!isValidDbToolToken(token)) return { error: "Couldn’t start the install — try again." };
827	  const path = `/nxtools-${token}/adminer.php`;
828	  await db.hostingTask.create({ data: { accountId, kind: "INSTALL_DBTOOL", payload: JSON.stringify({ token, path }) } });
829	  revalidatePath(`/dashboard/hosting/${accountId}`);
830	  return { ok: true };
831	}
