845	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
846	  const user = await requireUser();
847	  // A DONE task result can carry a one-time secret (the WordPress admin password);
848	  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
849	  await assertNotImpersonating();
850	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
851	  if (!a) return [];
852	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
853	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
854	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
855	  // then clear it so it isn't shown again on the next poll.
