859	  // needs long-term (WordPress passwords aren't recoverable). Those persist and are
860	  // surfaced in the Overview's App Credentials panel (getHostingAppCredentials).
861	  const toClear = rows.filter(
862	    (t) => t.status === "DONE" && t.result && t.kind !== "WORDPRESS_INSTALL" && t.kind !== "APP_INSTALL",
863	  );
864	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
