1000	/**
1001	 * Move a hosting account UP to a larger plan. Same purchase discipline as
1002	 * orderHostingAccount: no spending while impersonating, wallet charge in the same
1003	 * tx that mutates the account.
1004	 *
1005	 * Billing choice (kept simple + honest): we charge the FULL per-term price
1006	 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
1007	 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
1008	 * the flow one debit and never owes the customer money back. The customer sees the
1009	 * exact delta before confirming. Only UP is allowed (a downgrade would need a
1010	 * refund path we don't have).
1011	 */
1012	export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
1013	  const user = await requireUser();
1014	  await assertNotImpersonating();
1015	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
1016	  if (!a) return { error: "Account not found." };
1017	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
1018	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
1019	  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
1020	  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
1021	  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
1022	  const cur = a.plan;
1023	  // Up-only guard (re-checked server-side; never trust the client's picker).
1024	  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
1025	    return { error: "You can only move to a larger plan." };
1026	  }
1027	  const limits = planLimits(newPlan);
1028	  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
1029	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
1030	
1031	  try {
1032	    await db.$transaction(async (tx) => {
1033	      if (chargeCents > 0) {
1034	        await debitWallet(tx, user.id, chargeCents);
1035	        await tx.walletTransaction.create({
1036	          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
1037	        });
1038	      }
1039	      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
1040	      // does at creation), so a later plan edit can't silently re-quota this account.
1041	      // phpVersion is left as-is: an upgrade only widens the allowed set.
1042	      await tx.hostingAccount.update({
1043	        where: { id: a.id },
1044	        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
1045	      });
1046	      // Enact the node-level change (raise disk quota + rewrite FPM pool).
1047	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
1048	    });
1049	  } catch (e) {
1050	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
1051	    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
1052	  }
1053	
1054	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
1055	  revalidatePath(`/dashboard/hosting/${accountId}`);
1056	  return { ok: true };
1057	}
