1166	/**
1167	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
1168	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
1169	 * subdomain, or an addon domain. Before this, each creator only checked its own
1170	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
1171	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
1172	 *
1173	 * This is now a FAST, FRIENDLY PRE-CHECK only — good UX (an early, clear error)
1174	 * but NOT trusted alone: a non-atomic read can't stop two concurrent requests
1175	 * from both passing it and both committing the same server_name (the co-tenant
1176	 * vhost-shadowing TOCTOU). The authoritative guard is the atomic UNIQUE(hostname)
1177	 * insert into HostingHostnameClaim done INSIDE each creator's transaction — a
1178	 * colliding claim fails there (P2002) and rolls the whole tx back.
1179	 */
1180	async function isHostnameClaimed(name: string): Promise<boolean> {
1181	  // The authoritative registry (single UNIQUE(hostname) spanning all three kinds)
1182	  // is the fast, definitive pre-check now. We also still scan the three resource
1183	  // tables so any legacy row created before the claims table existed is honoured.
1184	  const host = normalizeClaimHostname(name);
1185	  const [claim, prim, sub, addon] = await Promise.all([
1186	    db.hostingHostnameClaim.count({ where: { hostname: host } }),
1187	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
1188	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
1189	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
1190	  ]);
1191	  return claim + prim + sub + addon > 0;
1192	}
