1458	/** Normalize a comma-separated PHP-version list to distinct, valid `\d.\d` tokens. */
1459	function normalizePhpVersions(raw: string): string {
1460	  const seen = new Set<string>();
1461	  for (const tok of raw.split(",").map((s) => s.trim()).filter(Boolean)) {
1462	    if (/^\d\.\d$/.test(tok)) seen.add(tok);
1463	  }
1464	  return [...seen].join(",");
1465	}
