80	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
81	function strongPassword(len = 22): string {
82	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
83	  const bytes = randomBytes(len);
84	  let out = "";
85	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
86	  return out;
87	}
