178	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
179	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
180	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
181	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
182	}
