185	 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
186	 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
187	 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
188	 * interpolation reaches a shell here (the caller validated every part).
189	 */
190	function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
191	  const phpLoc = [
192	    `    location ~ \\.php$ {`,
193	    `        include fastcgi_params;`,
194	    `        fastcgi_pass unix:${sock};`,
195	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
196	    `    }`,
197	  ].join("\n");
198	  const body = [
199	    `    root ${docroot};`,
200	    // Refuse a symlink whose target isn't owned by the link's owner — a tenant
201	    // can't symlink a neighbour's file into a served path (audit CRITICAL-1).
202	    `    disable_symlinks if_not_owner;`,
203	    `    index index.php index.html;`,
204	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
205	    phpLoc,
206	    `    location ~ /\\. { deny all; }`,
207	  ].join("\n");
208	  const http = [
209	    `server {`,
210	    `    listen 80;`,
211	    `    listen [::]:80;`,
212	    `    server_name ${serverName};`,
213	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
214	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
215	    `}`,
216	  ].join("\n");
217	  if (!sslLiveDir) return http + "\n";
218	  const https = [
219	    `server {`,
220	    `    listen 443 ssl;`,
221	    `    listen [::]:443 ssl;`,
222	    `    server_name ${serverName};`,
223	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
224	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
225	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
226	    body,
227	    `}`,
228	  ].join("\n");
229	  return `${http}\n${https}\n`;
230	}
