246	/** Write + (re)load an account's FPM pool for a given PHP version. The pool
247	 *  contents (the PHP isolation boundary) come from the tested pure generator in
248	 *  lib/hosting.ts — socket path is unchanged across versions so the vhost never
249	 *  needs editing when PHP is switched. */
250	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
251	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
252	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConfig(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
253	}
254	
255	/**
256	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
257	 * sweep once DNS points at us). Every interpolated value has already cleared a
258	 * validator, so nothing here can be a shell metacharacter.
259	 */
260	async function applyIsolation(
261	  conn: Client,
262	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
263	  php: string,
264	): Promise<void> {
265	  const u = a.username;
266	  const d = a.primaryDomain;
267	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
268	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
269	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
270	  const { home, webroot } = accountPaths(u);
271	  const quotaGB = Math.max(1, Math.round(a.diskQuotaMB / 1024));
272	  const hardBlocks = diskQuotaBlocks(quotaGB);
273	  const softBlocks = Math.floor(hardBlocks * 0.95);
274	  const inodes = diskQuotaInodes(quotaGB);
275	  const sock = `/run/php/${u}.sock`;
276	
277	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
278	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
279	  //
280	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
281	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
282	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
283	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
284	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
285	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
286	  const fs = accountFsPlan(u);
287	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
288	  await run(
289	    conn,
290	    "chroot-safe home",
291	    `mkdir -p ${webroot} ${home}/tmp && ` +
292	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
293	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
294	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
295	  );
296	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
297	
298	  // 2. Disk quota (fs must have usrquota — node onboarding enables it). The last
299	  //    two fields are the INODE soft/hard limits: `0 0` = unlimited inodes, which
300	  //    let a tenant exhaust the shared filesystem's inode table with millions of
301	  //    tiny files (a DoS the block quota can't stop), so we pass real caps (HIGH-2).
302	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} ${inodes.soft} ${inodes.hard} /home || echo 'quota tool absent — skipped'`);
303	
304	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
305	  await writeFpmPool(conn, u, home, webroot, php);
306	
307	  // 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
308	  //    second the account exists. Without this the account served HTTP-only until
309	  //    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
310	  //    while the panel already said "active" (the kaymo failure). Idempotent: only
311	  //    generated if absent. Key is 600 root; the whole dir is root-owned + off the
312	  //    tenant tree, so a tenant can never read or swap its own TLS key.
313	  const ssCertDir = selfSignedCertDir(u);
314	  await run(
315	    conn,
316	    "self-signed fallback cert",
317	    `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
318	      `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
319	      `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
320	      `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
321	      `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
322	  );
323	
324	  // 5. Name-based vhost — ALWAYS listens on 443, using the self-signed fallback
325	  //    until the SSL sweep swaps in the real Let's Encrypt cert.
326	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, { certDir: ssCertDir, real: false }));
327	
328	  // 5b. Branded placeholder so the account serves a real "site is ready" page from the
329	  //     first second (not a bare 403) until files are uploaded or an app is installed.
330	  await seedParkingPage(conn, fs.webroot.owner, webroot, d);
331	
332	  // 6. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
333	  const sftpConf = [
334	    `Match User ${u}`,
335	    `    ChrootDirectory ${home}`,
336	    `    ForceCommand internal-sftp`,
337	    `    AllowTcpForwarding no`,
338	    `    X11Forwarding no`,
339	  ].join("\n");
340	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
341	  await run(
342	    conn,
343	    "sftp chroot (guarded)",
344	    // Write to a temp include, validate the WHOLE sshd config, and only then move
345	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
346	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
347	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
348	  );
349	}
