353	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
354	async function provisionHostingDatabase(dbId: string): Promise<void> {
355	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
356	  if (!rec || rec.status !== "PENDING") return;
357	  if (SANDBOX || !ENABLED) {
358	    // KEEP the encrypted password (no longer nulled) so it stays viewable from the
359	    // panel in sandbox/dev and remains available once shared hosting is enabled.
360	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", error: SANDBOX ? null : "Shared hosting not enabled." } });
361	    return;
362	  }
363	  const name = rec.name;
364	  const user = rec.dbUser;
365	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
366	  // DB name + user were built from the validated username; re-assert shape.
367	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
368	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
369	    return;
370	  }
371	  try {
372	    const conn = await connectNode(rec.account.node);
373	    try {
374	      // Grants scoped to THIS database only — the data-isolation boundary.
375	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
376	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
377	      await run(conn, "create database", `mysql -e "${sql}"`);
378	    } finally {
379	      try { conn.end(); } catch { /* */ }
380	    }
381	    // KEEP the encrypted password on the row (no longer nulled) so the customer can
382	    // view it later from the Databases panel (revealHostingDbPassword). It was
383	    // stored encrypted at creation and never leaves the server except via the
384	    // owner-checked reveal action.
385	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", error: null } });
386	  } catch (e) {
387	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
388	  }
389	}
