398	export async function provisionHostingAccount(accountId: string): Promise<void> {
399	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
400	  if (!account || account.status !== "PENDING") return;
401	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
402	
403	  if (SANDBOX || !ENABLED) {
404	    if (SANDBOX) {
405	      const pw = strongPassword();
406	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
407	    } else {
408	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
409	    }
410	    return;
411	  }
412	
413	  try {
414	    const allowed = planLimits(account.plan).phpVersions;
415	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
416	    const sftpPassword = strongPassword();
417	    const conn = await connectNode(account.node);
418	    try {
419	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
420	    } finally {
421	      try { conn.end(); } catch { /* */ }
422	    }
423	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
424	    // Issue the real cert NOW instead of waiting up to a full sweep interval. A free
425	    // subdomain resolves via the *.sites wildcard the instant it's live, so certbot
426	    // succeeds immediately; a custom domain simply isn't pointed yet and is skipped
427	    // (the periodic sweep catches it once DNS lands). Best-effort — never fail a
428	    // completed provision because HTTPS issuance had a transient hiccup.
429	    await hostingSslSweep().catch((e) => console.error(`[hosting] post-provision SSL issue failed for ${account.id}`, e));
430	  } catch (e) {
431	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
432	  }
433	}
