442	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
443	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
444	  try {
445	    const a = await dns.resolve4(domain);
446	    return a.includes(ip);
447	  } catch {
448	    return false;
