629	// ---- Node hardening sweep (admin "Run setup / harden") ---------------------
630	
631	/**
632	 * Run `scripts/onboard-hosting-node.sh` on ONE admin-QUEUED node over the
633	 * platform's EXISTING SSH path (the node's stored encrypted root password, the
634	 * same credential the account provisioner already uses). This lets the owner
635	 * harden a node — ModSecurity WAF + ClamAV + the hardening steps — WITHOUT ever
636	 * knowing the node's root password. The onboard script is idempotent and
637	 * `nginx -t`-guarded, so a re-run is safe and can't reload a broken config.
638	 *
639	 * NOT gated on ENABLE_SHARED_HOSTING: hardening is preparatory work that should
640	 * run before selling is switched on. Only the SANDBOX branch differs — there is
641	 * no real box to SSH into, so it just simulates the result. The sweep NEVER
642	 * hardens on its own initiative: it only acts on a node an admin explicitly set
643	 * to QUEUED (via adminHardenHostingNode).
644	 */
645	export async function hostingNodeHardenSweep(): Promise<void> {
646	  if (SANDBOX) {
647	    // No real SSH in sandbox — mark every queued node done so staging can drive
648	    // the whole button → badge → log flow without a box.
649	    const queued = await db.hostingNode.findMany({ where: { hardenStatus: "QUEUED" }, select: { id: true } });
650	    for (const n of queued) {
651	      await db.hostingNode
652	        .update({ where: { id: n.id }, data: { hardenStatus: "DONE", hardenedAt: new Date(), hardenLog: "[sandbox] onboard script simulated" } })
653	        .catch(() => undefined);
654	    }
655	    return;
656	  }
657	
658	  // One node per tick, oldest QUEUED first — the run is minutes long, so we
659	  // don't want to hold several SSH sessions open at once.
660	  const node = await db.hostingNode.findFirst({ where: { hardenStatus: "QUEUED" }, orderBy: { createdAt: "asc" } });
661	  if (!node) return;
662	  // Claim it immediately so the next tick can't pick the same node up again.
663	  await db.hostingNode.update({ where: { id: node.id }, data: { hardenStatus: "RUNNING" } });
664	
665	  try {
666	    // The worker's WorkingDirectory is the app root, so the script sits alongside.
667	    const script = readFileSync(join(process.cwd(), "scripts/onboard-hosting-node.sh"), "utf8");
668	    // Base64 the whole script and reconstitute it on the node — no quoting/heredoc
669	    // hazard reaches the shell, and the payload is a single opaque token.
670	    const b64 = Buffer.from(script, "utf8").toString("base64");
671	    const conn = await connectNode(node);
672	    try {
673	      // Decode → run → capture rc → always remove the temp script → exit with rc,
674	      // so a non-zero onboard exit is faithfully reported as FAILED. 2>&1 folds
675	      // stderr into the captured combined `out`.
676	      const cmd =
677	        `set -o pipefail; printf %s '${b64}' | base64 -d > /root/.nxeon-onboard.sh && ` +
678	        `bash /root/.nxeon-onboard.sh 2>&1; rc=$?; rm -f /root/.nxeon-onboard.sh; exit $rc`;
679	      const { code, out } = await exec(conn, cmd, HARDEN_TIMEOUT_MS);
680	      await db.hostingNode.update({
681	        where: { id: node.id },
682	        data: {
683	          hardenStatus: code === 0 ? "DONE" : "FAILED",
684	          hardenedAt: new Date(),
685	          hardenLog: out.slice(-HARDEN_LOG_MAX),
686	        },
687	      });
688	    } finally {
689	      try { conn.end(); } catch { /* */ }
690	    }
691	  } catch (e) {
692	    // Any SSH/read/timeout error must leave a terminal state — never a node stuck
693	    // in RUNNING (which the action-level guard would then refuse to re-queue).
694	    await db.hostingNode
695	      .update({
696	        where: { id: node.id },
697	        data: { hardenStatus: "FAILED", hardenedAt: new Date(), hardenLog: (e instanceof Error ? e.message : String(e)).slice(-HARDEN_LOG_MAX) },
698	      })
699	      .catch(() => undefined);
700	  }
701	}
