875	/** Reverse a suspend: re-enable the site, rebuild the FPM pool, unlock the user. */
876	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
877	  assertLifecycleSafe(a);
878	  const { home, webroot } = accountPaths(a.username);
879	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
