255	/**
256	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
257	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
258	 * HTTPS actually refuses. Three overall states, per the account's measured health:
259	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
260	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
261	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
262	 */
263	function DnsStepper({ account }: { account: HostingAccountView }) {
264	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
265	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
266	  const verified = account.sslActive && account.serveHttpsOk !== false;
267	  const state: "verified" | "issuing" | "dns" | "pending" =
268	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
269	
270	  const free = account.isFreeSubdomain;
271	  const steps = [
272	    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
