274	      label: "Site live",
275	      done: state === "issuing" || state === "verified",
276	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
277	    },
278	    {
279	      label: "HTTPS verified",
280	      done: state === "verified",
281	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
282	    },
283	  ];
284	
285	  const headline =
286	    account.healthNote ??
287	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
288	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
289	
290	  return (
291	    <div className="mt-4">
292	      <div className="flex items-center">
293	        {steps.map((s, i) => (
