297	                {s.done ? "✓" : i + 1}
298	              </span>
299	            </div>
300	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
