137	/**
138	 * Inode (file-count) quota for `setquota`, the containment for a DoS the block
139	 * quota alone doesn't stop: a tenant creating MILLIONS of tiny files exhausts the
140	 * shared filesystem's inode table — filling no disk blocks but breaking every
141	 * neighbour's ability to create a file. `setquota … <isoft> <ihard>` of `0 0`
142	 * means UNLIMITED inodes, so a real cap is required here. Scales gently off the
143	 * plan's disk size but is floored (a 1 GB plan still gets working room) and
144	 * ceilinged (a huge plan can't effectively uncap); hard carries 25% headroom
145	 * over soft so a tenant hits the soft warning before the hard wall.
146	 */
147	export function diskQuotaInodes(diskGB: number): { soft: number; hard: number } {
148	  const gb = Math.max(1, Math.floor(diskGB || 1));
149	  const soft = Math.min(2_000_000, Math.max(200_000, gb * 50_000));
150	  const hard = Math.floor(soft * 1.25);
151	  return { soft, hard };
