/**
 * Resolve the install TARGET carried in a WORDPRESS_INSTALL / APP_INSTALL payload
 * to a concrete docroot + hostname on the node. Back-compat: when no target is
 * present (or `kind === "primary"`), the account's primary webroot + primaryDomain
 * are used exactly as before. For a subdomain/addon target the row is looked up
 * SCOPED TO THE ACCOUNT (the cross-tenant guard — the worker never trusts a raw
 * docroot from the payload) and must be ACTIVE; every shell-bound part is
 * re-validated here before it can reach a command.
 */
async function resolveInstallTarget(
  a: { id: string; username: string; primaryDomain: string },
  payload: string | null,
): Promise<{ docroot: string; hostname: string }> {
  const u = a.username;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  let target: { kind?: string; id?: string } = {};
  try {
    target = (JSON.parse(payload || "{}").target ?? {}) as { kind?: string; id?: string };
  } catch {
    target = {};
  }
  const kind = String(target.kind ?? "primary");
  const id = String(target.id ?? "");

  if (kind === "subdomain" && id) {
    const sub = await db.hostingSubdomain.findFirst({ where: { id, accountId: a.id } });
    if (!sub || sub.status !== "ACTIVE") throw new Error("target subdomain not found or not active");
    if (!isValidSubdomainLabel(sub.label)) throw new Error("unsafe subdomain label");
    const fqdn = `${sub.label}.${a.primaryDomain}`;
    if (!isValidHostingDomain(fqdn)) throw new Error("unsafe subdomain hostname");
    return { docroot: subdomainPaths(u, sub.label).docroot, hostname: fqdn };
  }
  if (kind === "addon" && id) {
    const addon = await db.hostingAddonDomain.findFirst({ where: { id, accountId: a.id } });
    if (!addon || addon.status !== "ACTIVE") throw new Error("target addon domain not found or not active");
    if (!isValidHostingDomain(addon.domain)) throw new Error("unsafe addon domain");
    return { docroot: addonDomainPaths(u, addon.domain).docroot, hostname: addon.domain };
  }
  // Default / primary.
  if (!isValidHostingDomain(a.primaryDomain)) throw new Error("unsafe account");
  return { docroot: accountPaths(u).webroot, hostname: a.primaryDomain };
}

