  if (app.needsDb) {
    if (a._count.databases >= a.maxDatabases) return { error: `This app needs a database, but your plan's ${a.maxDatabases} are used.` };
    // Per-site suffix keeps each site's DB name distinct (primary keeps `<user>_<slug>`).
    const dbName = `${a.username}_${slug}${tgt.dbSuffix}`.slice(0, 64);
    const dbUser = dbName.slice(0, 32);
    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
    payload = { ...payload, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
  }
  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}

// ---------- Unified "Websites" view -----------------------------------------

export type HostingWebsiteView = {
  /** Stable key: "primary" | "subdomain:<id>" | "addon:<id>". */
  key: string;
  kind: "primary" | "subdomain" | "addon";
  /** Row id for a subdomain/addon; null for the primary site. */
  id: string | null;
  hostname: string;
  /** Chroot-relative docroot for the file manager (e.g. `subdomains/shop/public_html`). */
  fileManagerPath: string;
  sslActive: boolean;
  status: string;
  /** "WordPress" / a catalog app name / null — derived from this account's DONE
   *  install tasks (best-effort; not a live filesystem probe). */
  installedApp: string | null;
  isFreeSubdomain: boolean;
  /** Only real addon domains can be promoted to primary. */
  canSetPrimary: boolean;
  phpVersion: string;
};

/**
 * Every website hosted on an account — the primary site plus each subdomain and
 * addon domain — as unified cards for the Websites panel. Owner or admin. The
 * installed-app label is derived from the account's DONE WordPress/app install
 * tasks (mapped to the site each targeted); it's an advisory hint, not a live probe
 * of the docroot.
 */
export async function listWebsites(accountId: string): Promise<HostingWebsiteView[]> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({
    where: { id: accountId },
    select: { id: true, userId: true, username: true, primaryDomain: true, status: true, sslActive: true, phpVersion: true },
  });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");

  const [subs, addons, tasks] = await Promise.all([
    db.hostingSubdomain.findMany({ where: { accountId, status: { not: "DELETING" } }, orderBy: { createdAt: "asc" } }),
    db.hostingAddonDomain.findMany({ where: { accountId, status: { not: "DELETING" } }, orderBy: { createdAt: "asc" } }),
    db.hostingTask.findMany({
      where: { accountId, status: "DONE", kind: { in: ["WORDPRESS_INSTALL", "APP_INSTALL"] } },
      orderBy: { createdAt: "desc" },
      select: { kind: true, payload: true, result: true },
    }),
  ]);

  // Map the newest install per target site → an app label.
  const appByKey = new Map<string, string>();
  for (const t of tasks) {
    let target: { kind?: string; id?: string } = {};
    try { target = (JSON.parse(t.payload || "{}").target ?? {}) as { kind?: string; id?: string }; } catch { /* */ }
    const key = target.kind === "subdomain" && target.id ? `subdomain:${target.id}`
      : target.kind === "addon" && target.id ? `addon:${target.id}`
      : "primary";
    if (appByKey.has(key)) continue; // newest wins (tasks are desc)
    let label = t.kind === "WORDPRESS_INSTALL" ? "WordPress" : "App";
    try { const r = JSON.parse(t.result || "{}"); if (r?.app) label = String(r.app); } catch { /* */ }
    appByKey.set(key, label);
  }

  const cards: HostingWebsiteView[] = [
    {
      key: "primary",
      kind: "primary",
      id: null,
      hostname: a.primaryDomain,
      fileManagerPath: "public_html",
      sslActive: a.sslActive,
      status: a.status,
      installedApp: appByKey.get("primary") ?? null,
      isFreeSubdomain: isFreeSubdomain(a.primaryDomain),
      canSetPrimary: false,
      phpVersion: a.phpVersion,
    },
  ];
  for (const s of subs) {
    cards.push({
      key: `subdomain:${s.id}`,
      kind: "subdomain",
      id: s.id,
      hostname: s.fqdn,
      fileManagerPath: `subdomains/${s.label}/public_html`,
      sslActive: s.sslActive,
      status: s.status,
      installedApp: appByKey.get(`subdomain:${s.id}`) ?? null,
      isFreeSubdomain: false,
      canSetPrimary: false,
      phpVersion: a.phpVersion,
    });
  }
  for (const d of addons) {
    cards.push({
      key: `addon:${d.id}`,
      kind: "addon",
      id: d.id,
      hostname: d.domain,
      fileManagerPath: `domains/${d.domain}/public_html`,
      sslActive: d.sslActive,
      status: d.status,
      installedApp: appByKey.get(`addon:${d.id}`) ?? null,
      isFreeSubdomain: false,
      canSetPrimary: d.status === "ACTIVE",
      phpVersion: a.phpVersion,
    });
  }
  return cards;
}

/**
 * Promote an ACTIVE addon domain to the account's PRIMARY domain. Owner or admin,
 * never while impersonating (same discipline as every resource-mutating action).
 * The DB `primaryDomain` is NOT flipped here — the worker (taskSetPrimaryDomain)
 * flips it only after the node vhost + WordPress URL rewrite succeed, keeping the
 * old address serving as an alias in the meantime (worst-case safe). Idempotent
 * against double-click: refuses if a promotion is already queued/running.
 */
export async function setPrimaryHostingDomain(accountId: string, addonId: string): Promise<HostingResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, primaryDomain: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId }, select: { id: true, domain: true, status: true } });
  if (!addon) return { error: "That domain isn’t part of this account." };
  if (addon.status !== "ACTIVE") return { error: "That domain is still being set up — wait until it’s live, then try again." };
  if (addon.domain === a.primaryDomain) return { error: "That’s already your primary domain." };
  const inFlight = await db.hostingTask.findFirst({
    where: { accountId, kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"], status: { in: ["PENDING", "RUNNING"] } },
  });
  if (inFlight) return { error: "A primary-domain change is already in progress." };
  await db.hostingTask.create({
    data: {
      accountId,
      kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"],
      payload: JSON.stringify({ addonId: addon.id, newDomain: addon.domain, oldDomain: a.primaryDomain }),
    },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "hosting.setprimary", detail: `${a.primaryDomain} → ${addon.domain}` } }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

