"use client";

import { useCallback, useEffect, useState } from "react";
import {
  listWebsites,
  installWordPress,
  installApp,
  listAppCatalog,
  setPrimaryHostingDomain,
  deleteSubdomain,
  deleteAddonDomain,
  type HostingWebsiteView,
  type SiteTarget,
} from "@/lib/actions-hosting";
import { StatusPill } from "@/components/customer/cpanel/shared";
import { Badge } from "@/components/ui/primitives";

/** The install target for a website card. */
function targetOf(w: HostingWebsiteView): SiteTarget {
  if (w.kind === "subdomain" && w.id) return { kind: "subdomain", id: w.id };
  if (w.kind === "addon" && w.id) return { kind: "addon", id: w.id };
  return { kind: "primary" };
}

/**
 * Unified "Websites" panel: the account's primary site plus every subdomain and
 * addon domain, each as a card with its own actions — install WordPress / an app
 * onto THAT site, open its files, promote an addon domain to primary, or delete a
 * subdomain / addon. On-brand with the rest of the hosting panels.
 */
export function WebsitesPanel({ accountId }: { accountId: string }) {
  const [rows, setRows] = useState<HostingWebsiteView[] | null>(null);
  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);
  const [busyKey, setBusyKey] = useState<string | null>(null);
  const [err, setErr] = useState("");

  const refresh = useCallback(() => {
    listWebsites(accountId).then(setRows).catch(() => setRows([]));
  }, [accountId]);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);

  // Poll while anything is settling (a new site provisioning, or an ACTIVE site
  // still waiting on its HTTPS certificate) so badges appear without a manual reload.
  useEffect(() => {
    if (!rows?.some((r) => r.status === "PENDING" || r.status === "DELETING" || (r.status === "ACTIVE" && !r.sslActive))) return;
    const t = setInterval(refresh, 5000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  async function doInstall(w: HostingWebsiteView, value: string) {
    if (!value) return;
    setBusyKey(w.key); setErr("");
    const r = value === "wordpress"
      ? await installWordPress(accountId, targetOf(w))
      : await installApp(accountId, value, targetOf(w));
    setBusyKey(null);
    if (r.error) setErr(r.error); else refresh();
  }

  async function promote(w: HostingWebsiteView) {
    if (!w.id) return;
    if (!confirm(`Make ${w.hostname} your primary domain? Your main website (public_html) will answer on ${w.hostname}, and your old address will keep working as an alias.`)) return;
    setBusyKey(w.key); setErr("");
    const r = await setPrimaryHostingDomain(accountId, w.id);
    setBusyKey(null);
    if (r.error) setErr(r.error); else refresh();
  }

  async function remove(w: HostingWebsiteView) {
    if (!w.id) return;
    if (!confirm(`Delete ${w.hostname}? Its files will be removed.`)) return;
    setBusyKey(w.key); setErr("");
    const r = w.kind === "subdomain" ? await deleteSubdomain(w.id) : await deleteAddonDomain(w.id);
    setBusyKey(null);
    if (r.error) setErr(r.error); else refresh();
  }

  function openFiles(w: HostingWebsiteView) {
    window.location.href = `/dashboard/hosting/${accountId}?tab=files&path=${encodeURIComponent(w.fileManagerPath)}`;
  }

  const kindLabel: Record<HostingWebsiteView["kind"], string> = { primary: "Primary", subdomain: "Subdomain", addon: "Addon domain" };

  return (
    <div className="card">
      <div className="mb-4">
        <h3 className="font-semibold">Websites</h3>
        <p className="mt-1 text-sm text-slate-400">
          Every site on this account — your primary domain, subdomains and addon domains. Install WordPress or an app onto
          any one of them, open its files, or promote a domain to primary. Add new subdomains and addon domains from the{" "}
          <span className="text-slate-300">Domains</span> tab.
        </p>
      </div>

      {err && <p className="mb-3 text-sm text-red-400">{err}</p>}

      {rows === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : (
        <ul className="space-y-3">
          {rows.map((w) => {
            const busy = busyKey === w.key;
            const settling = w.status === "PENDING" || w.status === "DELETING";
            return (
              <li key={w.key} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <a
                        href={w.sslActive ? `https://${w.hostname}` : `http://${w.hostname}`}
                        target="_blank"
                        rel="noreferrer"
                        className="truncate font-mono text-sm text-slate-100 hover:underline"
                      >
                        {w.hostname}
                      </a>
                      <Badge tone="slate">{kindLabel[w.kind]}</Badge>
                      {w.isFreeSubdomain && <Badge tone="brand">free subdomain</Badge>}
                      <StatusPill status={w.status} />
                      {w.sslActive ? <Badge tone="green">HTTPS</Badge> : <Badge tone="amber">HTTP</Badge>}
                    </div>
                    <div className="mt-1.5 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-slate-500">
                      <span>App: <span className="text-slate-300">{w.installedApp ?? "None"}</span></span>
                      <span>PHP <span className="font-mono text-slate-300">{w.phpVersion}</span></span>
                      <span className="font-mono">{w.fileManagerPath}</span>
                    </div>
                  </div>
                </div>

                <div className="mt-3 flex flex-wrap items-center gap-2">
                  {/* Install WordPress / an app onto THIS site */}
                  <label className="flex items-center gap-1.5 text-xs text-slate-400">
                    <span className="sr-only">Install app</span>
                    <select
                      className="input py-1 text-xs"
                      defaultValue=""
                      disabled={busy || settling}
                      onChange={(e) => { const v = e.target.value; e.currentTarget.value = ""; doInstall(w, v); }}
                    >
                      <option value="">{busy ? "Working…" : "Install app…"}</option>
                      <option value="wordpress">WordPress (auto)</option>
                      {apps.map((ap) => (<option key={ap.slug} value={ap.slug}>{ap.name}</option>))}
                    </select>
                  </label>

                  <button className="btn-secondary px-2.5 py-1 text-xs" disabled={settling} onClick={() => openFiles(w)}>
                    Open files
                  </button>

                  {w.canSetPrimary && (
                    <button className="btn-secondary px-2.5 py-1 text-xs" disabled={busy || settling} onClick={() => promote(w)}>
                      Set as primary
                    </button>
                  )}

                  {(w.kind === "subdomain" || w.kind === "addon") && (
                    <button className="btn-danger px-2.5 py-1 text-xs" disabled={busy || settling} onClick={() => remove(w)}>
                      Delete
                    </button>
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

