/**
 * Extra server_name ALIASES the account's PRIMARY vhost must keep serving: every
 * PRIMARY-kind hostname claim OTHER than the current primaryDomain. Normally empty
 * (an account has exactly one PRIMARY claim = its own domain) → the primary vhost is
 * rendered exactly as before. After taskSetPrimaryDomain promotes an addon, the OLD
 * primary is retained as a second PRIMARY claim and surfaces here, so every later
 * reinstall of the primary vhost (SSL sweep, health self-heal) keeps the old address
 * alive instead of silently dropping it on the next cert reissue.
 */
async function primaryAliasesFor(accountId: string, primaryDomain: string): Promise<string[]> {
  const cur = normalizeClaimHostname(primaryDomain);
  const claims = await db.hostingHostnameClaim
    .findMany({ where: { accountId, kind: "PRIMARY" }, select: { hostname: true } })
    .catch(() => [] as { hostname: string }[]);
